/**
 * Python `str.isprintable()` semantics.
 *
 * CPython defines a character as non-printable when its Unicode general
 * category is "Other" (Cc, Cf, Cs, Co, Cn) or "Separator" (Zl, Zp, Zs),
 * with the single exception of ASCII space (U+0020), which *is* printable.
 *
 * V8 exposes the Unicode character database through regular-expression
 * property escapes, so the category test needs no data tables of our own.
 */

const NON_PRINTABLE = /[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]/u;

const SPACE = 0x20;

/**
 * @param {number} cp a Unicode code point
 * @returns {boolean} true when Python would consider the code point printable
 */
export function isPrintableCodePoint(cp) {
  if (cp === SPACE) return true; // ASCII space: category Zs, but printable
  return !NON_PRINTABLE.test(String.fromCodePoint(cp));
}

/**
 * Iterate a JS string by Unicode code point, the way Python iterates `str`.
 *
 * Lone surrogates (which JS strings may legally contain) are yielded as-is so
 * that they can be escaped individually, matching CPython's repr of a string
 * holding unpaired surrogates.
 *
 * @param {string} s
 * @returns {Generator<number>} code points in order
 */
export function* codePoints(s) {
  for (const ch of s) {
    yield ch.codePointAt(0);
  }
}

/**
 * Python's `str.isprintable()` for a whole string.
 *
 * Note that Python returns true for the empty string.
 *
 * @param {string} s
 * @returns {boolean}
 */
export function isPrintable(s) {
  for (const cp of codePoints(s)) {
    if (!isPrintableCodePoint(cp)) return false;
  }
  return true;
}

