/**
 * Python `str` methods whose behaviour differs from the JS equivalents.
 */

/**
 * Code points Python treats as line boundaries in `str.splitlines()`.
 *
 * This is a strictly larger set than the `\n` that `String.prototype.split`
 * would suggest: it includes the C0 separators, NEL, and the Unicode line and
 * paragraph separators. `\r\n` counts as a single boundary.
 */
const LINE_BOUNDARIES = new Set([
  0x0a, // \n   line feed
  0x0b, // \v   line tabulation
  0x0c, // \f   form feed
  0x0d, // \r   carriage return
  0x1c, //      file separator
  0x1d, //      group separator
  0x1e, //      record separator
  0x85, //      next line (NEL)
  0x2028, //    line separator
  0x2029, //    paragraph separator
]);

const LF = 0x0a;
const CR = 0x0d;

/**
 * Python's `str.splitlines()`.
 *
 * Unlike `split('\n')`, a trailing line boundary does not produce a final
 * empty element, and the empty string yields an empty list.
 *
 * @param {string} s
 * @returns {string[]}
 */
export function splitlines(s) {
  const lines = [];
  let start = 0;
  let i = 0;

  while (i < s.length) {
    const code = s.charCodeAt(i);
    if (!LINE_BOUNDARIES.has(code)) {
      i += 1;
      continue;
    }
    lines.push(s.slice(start, i));
    // \r\n is one boundary, not two.
    i += code === CR && s.charCodeAt(i + 1) === LF ? 2 : 1;
    start = i;
  }

  if (start < s.length) lines.push(s.slice(start));
  return lines;
}

