/**
 * Python's `repr()` for the value shapes this program can produce.
 */

import { codePoints, isPrintableCodePoint } from './unicode.mjs';
import { PyDict } from './dict.mjs';

const BACKSLASH = 0x5c;
const SQUOTE = 0x27;
const DQUOTE = 0x22;
const TAB = 0x09;
const LF = 0x0a;
const CR = 0x0d;

/** Lowercase hex, zero padded — CPython emits `\xad`, never `\xAD`. */
function hex(cp, width) {
  return cp.toString(16).padStart(width, '0');
}

/**
 * Python's `repr()` of a `str`.
 *
 * Quote selection follows CPython: single quotes are preferred; a string that
 * contains `'` but no `"` is wrapped in double quotes instead; a string that
 * contains both is wrapped in single quotes with the single quotes escaped.
 *
 * @param {string} s
 * @returns {string}
 */
export function reprStr(s) {
  const hasSingle = s.includes("'");
  const hasDouble = s.includes('"');
  const quote = hasSingle && !hasDouble ? DQUOTE : SQUOTE;
  const quoteChar = String.fromCodePoint(quote);

  let out = quoteChar;
  for (const cp of codePoints(s)) {
    if (cp === quote || cp === BACKSLASH) {
      out += '\\' + String.fromCodePoint(cp);
    } else if (cp === TAB) {
      out += '\\t';
    } else if (cp === LF) {
      out += '\\n';
    } else if (cp === CR) {
      out += '\\r';
    } else if (isPrintableCodePoint(cp)) {
      out += String.fromCodePoint(cp);
    } else if (cp < 0x100) {
      out += '\\x' + hex(cp, 2);
    } else if (cp < 0x10000) {
      out += '\\u' + hex(cp, 4);
    } else {
      out += '\\U' + hex(cp, 8);
    }
  }
  return out + quoteChar;
}

/**
 * Python's `repr()` dispatched over the value kinds a diff result contains.
 *
 * @param {unknown} value
 * @returns {string}
 */
export function repr(value) {
  if (typeof value === 'string') return reprStr(value);
  if (value instanceof PyDict) return reprDict(value);
  if (value === null) return 'None';
  if (value === true) return 'True';
  if (value === false) return 'False';
  return String(value);
}

/**
 * Python's `repr()` of a `dict`: `{}` when empty, otherwise
 * `{key: value, key: value}` in insertion order.
 *
 * @param {PyDict} dict
 * @returns {string}
 */
export function reprDict(dict) {
  const parts = [];
  for (const [key, value] of dict.entries()) {
    parts.push(`${repr(key)}: ${repr(value)}`);
  }
  return '{' + parts.join(', ') + '}';
}

