/**
 * An insertion-ordered mapping that reprs like a Python `dict`.
 *
 * A plain object would be unsafe here: diff keys come from user input, so a key
 * such as `__proto__` must be stored as data rather than mutating a prototype.
 * `Map` gives us that plus Python's insertion-order iteration for free.
 */
export class PyDict {
  constructor(entries = []) {
    /** @type {Map<string, unknown>} */
    this._map = new Map(entries);
  }

  get size() {
    return this._map.size;
  }

  has(key) {
    return this._map.has(key);
  }

  get(key) {
    return this._map.get(key);
  }

  set(key, value) {
    this._map.set(key, value);
    return this;
  }

  /**
   * Python's `dict.setdefault()`.
   */
  setdefault(key, fallback) {
    if (!this._map.has(key)) this._map.set(key, fallback);
    return this._map.get(key);
  }

  entries() {
    return this._map.entries();
  }

  keys() {
    return this._map.keys();
  }

  /** Rendered by `repr.mjs`; kept out of this module to avoid a cycle. */
  toString() {
    // Late import keeps `dict` free of a hard dependency on `repr`.
    return reprHook(this);
  }
}

/**
 * `PyDict.toString()` needs `reprDict`, but `repr.mjs` imports `PyDict` to do
 * its instance check. Resolving the formatter lazily breaks the import cycle.
 */
let reprHook = (dict) => `PyDict(${dict.size})`;

/** @param {(dict: PyDict) => string} fn */
export function setPyDictFormatter(fn) {
  reprHook = fn;
}

