/**
 * A port of Python's `difflib.SequenceMatcher`.
 *
 * The exact opcode stream matters: it is what decides which lines a unified
 * diff labels as context, deletion, or insertion. Reproducing difflib's
 * particular greedy "longest matching block, then recurse on both sides"
 * strategy — rather than a textbook minimal edit script — is therefore load
 * bearing, and so is its autojunk heuristic.
 */

/** @typedef {{ a: number, b: number, size: number }} Match */
/** @typedef {[string, number, number, number, number]} Opcode */

export class SequenceMatcher {
  /**
   * @param {((element: string) => boolean) | null} isjunk
   * @param {string[]} a  the "from" sequence
   * @param {string[]} b  the "to" sequence
   * @param {boolean} autojunk enable the popular-element heuristic
   */
  constructor(isjunk = null, a = [], b = [], autojunk = true) {
    this.isjunk = isjunk;
    this.a = a;
    this.b = b;
    this.autojunk = autojunk;
    /** @type {Match[] | null} */
    this.matchingBlocks = null;
    /** @type {Opcode[] | null} */
    this.opcodes = null;
    this._chainB();
  }

  /**
   * Index `b`, then drop junk and "popular" elements from the index.
   *
   * Popular elements are only removed from `b2j`; they are deliberately *not*
   * added to the junk set, so `findLongestMatch` still extends matches across
   * them. That is why a 250-line file with a heavily repeated line still
   * produces a tight diff.
   */
  _chainB() {
    const b = this.b;
    /** @type {Map<string, number[]>} */
    const b2j = new Map();
    for (let i = 0; i < b.length; i += 1) {
      const indices = b2j.get(b[i]);
      if (indices === undefined) b2j.set(b[i], [i]);
      else indices.push(i);
    }

    /** @type {Set<string>} */
    const junk = new Set();
    if (this.isjunk) {
      for (const element of b2j.keys()) {
        if (this.isjunk(element)) junk.add(element);
      }
      for (const element of junk) b2j.delete(element);
    }

    /** @type {Set<string>} */
    const popular = new Set();
    const n = b.length;
    if (this.autojunk && n >= 200) {
      const ntest = Math.floor(n / 100) + 1;
      for (const [element, indices] of b2j.entries()) {
        if (indices.length > ntest) popular.add(element);
      }
      for (const element of popular) b2j.delete(element);
    }

    this.b2j = b2j;
    this.bjunk = junk;
    this.bpopular = popular;
  }

  /**
   * Find the longest matching block in `a[alo:ahi]` / `b[blo:bhi]`.
   *
   * Ties are broken exactly as difflib breaks them: the earliest match in `a`
   * wins, and among those the earliest in `b`, because `>` (not `>=`) guards
   * the update of the running best.
   *
   * @returns {Match}
   */
  findLongestMatch(alo, ahi, blo, bhi) {
    const { a, b, b2j, bjunk } = this;
    let besti = alo;
    let bestj = blo;
    let bestsize = 0;

    // j2len[j] = length of the longest match ending at a[i-1], b[j-1].
    /** @type {Map<number, number>} */
    let j2len = new Map();
    for (let i = alo; i < ahi; i += 1) {
      /** @type {Map<number, number>} */
      const newj2len = new Map();
      const indices = b2j.get(a[i]);
      if (indices !== undefined) {
        for (const j of indices) {
          if (j < blo) continue;
          if (j >= bhi) break; // indices are ascending, so we can stop early
          const k = (j2len.get(j - 1) ?? 0) + 1;
          newj2len.set(j, k);
          if (k > bestsize) {
            besti = i - k + 1;
            bestj = j - k + 1;
            bestsize = k;
          }
        }
      }
      j2len = newj2len;
    }

    // Extend the match with non-junk elements on both ends. The index skipped
    // popular elements, so this is what recovers them.
    while (
      besti > alo &&
      bestj > blo &&
      !bjunk.has(b[bestj - 1]) &&
      a[besti - 1] === b[bestj - 1]
    ) {
      besti -= 1;
      bestj -= 1;
      bestsize += 1;
    }
    while (
      besti + bestsize < ahi &&
      bestj + bestsize < bhi &&
      !bjunk.has(b[bestj + bestsize]) &&
      a[besti + bestsize] === b[bestj + bestsize]
