    blocks.sort((x, y) => x.a - y.a || x.b - y.b || x.size - y.size);

    // Collapse adjacent equal blocks.
    /** @type {Match[]} */
    const nonAdjacent = [];
    let i1 = 0;
    let j1 = 0;
    let k1 = 0;
    for (const { a: i2, b: j2, size: k2 } of blocks) {
      if (i1 + k1 === i2 && j1 + k1 === j2) {
