    return answer;
  }

  /**
   * Opcodes chunked into hunks with up to `n` lines of surrounding context.
   *
   * @param {number} n
   * @returns {Opcode[][]}
   */
  getGroupedOpcodes(n = 3) {
    let codes = this.getOpcodes();
    if (codes.length === 0) codes = [['equal', 0, 1, 0, 1]];

    // Trim leading and trailing runs of context down to n lines.
    if (codes[0][0] === 'equal') {
      const [tag, i1, i2, j1, j2] = codes[0];
      codes[0] = [tag, Math.max(i1, i2 - n), i2, Math.max(j1, j2 - n), j2];
    }
    const last = codes.length - 1;
    if (codes[last][0] === 'equal') {
      const [tag, i1, i2, j1, j2] = codes[last];
      codes[last] = [tag, i1, Math.min(i2, i1 + n), j1, Math.min(j2, j1 + n)];
    }

    const nn = n + n;
    /** @type {Opcode[][]} */
    const groups = [];
    /** @type {Opcode[]} */
    let group = [];
    for (const code of codes) {
      let [tag, i1, i2, j1, j2] = code;
      // A long stretch of unchanged lines ends the hunk and starts a new one.
      if (tag === 'equal' && i2 - i1 > nn) {
        group.push([tag, i1, Math.min(i2, i1 + n), j1, Math.min(j2, j1 + n)]);
        groups.push(group);
        group = [];
        i1 = Math.max(i1, i2 - n);
        j1 = Math.max(j1, j2 - n);
      }
      group.push([tag, i1, i2, j1, j2]);
    }
    if (group.length > 0 && !(group.length === 1 && group[0][0] === 'equal')) {
      groups.push(group);
    }
    return groups;
  }
}

