/**
 * A port of Python's `difflib.unified_diff`.
 */

import { SequenceMatcher } from './sequence_matcher.mjs';

/**
 * Format one side of a hunk header.
 *
 * A single-line range is written without a length, and an empty range is
 * anchored to the line *before* it — which is what produces the familiar
 * `@@ -0,0 +1,2 @@` for "inserted at the top of an empty file".
 *
 * @param {number} start
 * @param {number} stop
 * @returns {string}
 */
function formatRangeUnified(start, stop) {
  let beginning = start + 1; // lines are numbered from one
  const length = stop - start;
  if (length === 1) return String(beginning);
  if (length === 0) beginning -= 1;
  return `${beginning},${length}`;
}

/**
 * Generate a unified diff of two sequences of lines.
 *
 * @param {string[]} a
 * @param {string[]} b
 * @param {object} [options]
 * @param {string} [options.fromfile]
 * @param {string} [options.tofile]
 * @param {string} [options.fromfiledate]
 * @param {string} [options.tofiledate]
 * @param {number} [options.n] lines of context
 * @param {string} [options.lineterm] appended to the header lines
 * @returns {string[]}
 */
export function unifiedDiff(a, b, options = {}) {
  const {
    fromfile = '',
    tofile = '',
    fromfiledate = '',
    tofiledate = '',
    n = 3,
    lineterm = '\n',
  } = options;

  /** @type {string[]} */
  const out = [];
  let started = false;

  const matcher = new SequenceMatcher(null, a, b);
  for (const group of matcher.getGroupedOpcodes(n)) {
    if (!started) {
      started = true;
      const fromdate = fromfiledate ? `\t${fromfiledate}` : '';
      const todate = tofiledate ? `\t${tofiledate}` : '';
      // The trailing space after --- / +++ is part of difflib's format even
      // when the filename is empty.
      out.push(`--- ${fromfile}${fromdate}${lineterm}`);
      out.push(`+++ ${tofile}${todate}${lineterm}`);
    }

    const first = group[0];
    const last = group[group.length - 1];
    const file1Range = formatRangeUnified(first[1], last[2]);
    const file2Range = formatRangeUnified(first[3], last[4]);
    out.push(`@@ -${file1Range} +${file2Range} @@${lineterm}`);

    for (const [tag, i1, i2, j1, j2] of group) {
      if (tag === 'equal') {
        for (const line of a.slice(i1, i2)) out.push(' ' + line);
        continue;
      }
      if (tag === 'replace' || tag === 'delete') {
        for (const line of a.slice(i1, i2)) out.push('-' + line);
      }
      if (tag === 'replace' || tag === 'insert') {
        for (const line of b.slice(j1, j2)) out.push('+' + line);
      }
    }
  }

  return out;
}

