 * An unchanged comparison renders as `{}` — report types with nothing to say
 * are omitted entirely rather than mapped to an empty dict.
 */

import { PyDict } from '../pycompat/index.mjs';

export class TextResult {
  constructor() {
    /** @type {PyDict} */
    this.root = new PyDict();
  }

  /**
   * Record one finding.
   *
   * @param {string} reportType e.g. `values_changed`
   * @param {string} path the affected path, e.g. `root`
   * @param {PyDict} detail per-path payload
   */
  report(reportType, path, detail) {
    const bucket = this.root.setdefault(reportType, new PyDict());
    bucket.set(path, detail);
  }

  get size() {
    return this.root.size;
  }

  /** Renders exactly as Python's `print(DeepDiff(...))` would. */
  toString() {
    return String(this.root);
  }
}

