/**
 * String comparison, the one report DeepDiff can emit for two `str` values.
 */

import { PyDict, splitlines } from '../pycompat/index.mjs';
import { unifiedDiff } from '../difflib/index.mjs';

/**
 * DeepDiff attaches a human-readable unified diff to a `values_changed` report
 * only when at least one side is multi-line. Note the trigger is specifically
 * the presence of `\n` — a string broken only by a bare `\r` is treated as a
 * single line and gets no `diff` key, even though `splitlines()` would split
 * it. The two rules disagreeing is intentional upstream behaviour, not a bug
 * to smooth over here.
 *
 * @param {string} t1 old value
 * @param {string} t2 new value
 * @returns {string | null} the diff text, or null when there is none to add
 */
export function stringDiff(t1, t2) {
  if (!t1.includes('\n') && !t2.includes('\n')) return null;

  const lines = unifiedDiff(splitlines(t1), splitlines(t2), { lineterm: '' });
  // Values can differ while their lines do not (e.g. 'a\n' vs 'a'), leaving an
  // empty diff. DeepDiff drops the key rather than reporting an empty string.
