/**
 * Usage and help rendering, matching `argparse.HelpFormatter`'s layout.
 */

/** argparse's own defaults. */
const INDENT = 2;
const MAX_HELP_POSITION = 24;

/**
 * How an action is spelled in the usage line: `--a A`, or just `-h` for a flag.
 *
 * @param {object} action
 * @returns {string}
 */
function formatUsagePart(action) {
  const optionString = action.optionStrings[0];
  if (action.nargs === 0) return optionString;
  return `${optionString} ${action.metavar}`;
}

/**
 * `usage: prog [-h] --a A --b B`
 *
 * Optional actions are bracketed; required ones are not.
 *
 * @param {string} prog
 * @param {object[]} actions
 * @returns {string}
 */
export function formatUsage(prog, actions) {
  const parts = actions.map((action) => {
    const part = formatUsagePart(action);
    return action.required ? part : `[${part}]`;
  });
  return `usage: ${[prog, ...parts].join(' ')}\n`;
}

/**
 * How an action is spelled in the options list: all its flags, comma joined,
 * with the metavar repeated after each one that takes a value.
 *
 * @param {object} action
 * @returns {string}
 */
function formatInvocation(action) {
  if (action.nargs === 0) return action.optionStrings.join(', ');
  return action.optionStrings.map((s) => `${s} ${action.metavar}`).join(', ');
}

/**
 * The full `--help` output.
 *
 * The help column is placed the way argparse places it: two past the widest
 * invocation, capped at column 24. Actions with no help text emit no trailing
 * padding at all.
 *
 * @param {string} prog
 * @param {object[]} actions
 * @returns {string}
 */
export function formatHelp(prog, actions) {
  const invocations = actions.map(formatInvocation);
  const actionMaxLength = Math.max(
    ...invocations.map((text) => text.length + INDENT),
  );
  const helpPosition = Math.min(actionMaxLength + 2, MAX_HELP_POSITION);

  const lines = [formatUsage(prog, actions), '\n', 'options:\n'];
  actions.forEach((action, i) => {
    const invocation = invocations[i];
    if (!action.help) {
      lines.push(`${' '.repeat(INDENT)}${invocation}\n`);
      return;
    }
    const head = `${' '.repeat(INDENT)}${invocation}`;
    if (head.length < helpPosition) {
      lines.push(`${head.padEnd(helpPosition)}${action.help}\n`);
    } else {
      // Too wide to share a line: help goes on the next one, indented.
      lines.push(`${head}\n${' '.repeat(helpPosition)}${action.help}\n`);
    }
  });

  return lines.join('');
}

