/**
 * A behavioural port of the slice of `argparse.ArgumentParser` that
 * `test1.py` uses: long options that each take exactly one value, plus the
 * automatic `-h/--help`.
 *
 * The fiddly rules reproduced here — all observable from the CLI — are:
 *   - `--opt=value` as well as `--opt value`
 *   - unique-prefix abbreviation, so `--h` resolves to `--help`
 *   - a value starting with `-` is rejected as "expected one argument", unless
 *     it looks like a negative number, is a bare `-`, or contains a space
 *   - `--` is not a value and never gets consumed as one
 *   - a missing required option is reported *before* unrecognized arguments
 */

import { formatHelp, formatUsage } from './formatter.mjs';

/** Thrown instead of calling `process.exit` so the parser stays testable. */
export class ExitError extends Error {
  /**
   * @param {number} status
   * @param {string} stdout
   * @param {string} stderr
   */
  constructor(status, stdout, stderr) {
    super(stderr || stdout);
    this.status = status;
    this.stdout = stdout;
    this.stderr = stderr;
  }
}

const PREFIX_CHARS = '-';

/**
 * Python's `re` module matches any Unicode decimal digit with `\d`, so
 * `\p{Nd}` — not `[0-9]` — is the faithful spelling here.
 */
const NEGATIVE_NUMBER = /^-\p{Nd}+$|^-\p{Nd}*\.\p{Nd}+$/u;

export class ArgumentParser {
  /**
   * @param {object} [options]
   * @param {string} [options.prog]
   */
  constructor({ prog = 'prog' } = {}) {
    this.prog = prog;
    /** @type {object[]} */
    this.actions = [];
    /** @type {Map<string, object>} */
    this.optionStringActions = new Map();

    this.addArgument(['-h', '--help'], {
      action: 'help',
      help: 'show this help message and exit',
    });
  }

  /**
   * @param {string[]} optionStrings e.g. `['--a']`
   * @param {object} [options]
   * @param {'store'|'help'} [options.action]
   * @param {boolean} [options.required]
   * @param {string} [options.help]
   */
  addArgument(optionStrings, { action = 'store', required = false, help = '' } = {}) {
    const dest = optionStrings[optionStrings.length - 1].replace(/^--?/, '');
    const entry = {
      optionStrings,
      dest,
      action,
      required,
      help,
      nargs: action === 'help' ? 0 : null,
      // argparse derives the metavar from the dest by upper-casing it.
      metavar: dest.toUpperCase(),
    };
    this.actions.push(entry);
    for (const optionString of optionStrings) {
      this.optionStringActions.set(optionString, entry);
    }
    return entry;
  }

  formatUsage() {
    return formatUsage(this.prog, this.actions);
  }

  formatHelp() {
    return formatHelp(this.prog, this.actions);
  }

  /** Mirrors `parser.error()`: usage plus one message on stderr, exit code 2. */
  error(message) {
    throw new ExitError(2, '', `${this.formatUsage()}${this.prog}: error: ${message}\n`);
  }

  /**
   * All option strings that `prefix` could be an abbreviation of.
   *
   * @param {string} argString
   * @returns {{action: object, optionString: string, explicitArg: string|null}[]}
   */
  _getOptionTuples(argString) {
    const result = [];
    const isLong =
      PREFIX_CHARS.includes(argString[0]) && PREFIX_CHARS.includes(argString[1]);
    if (!isLong) return result;

    let optionPrefix = argString;
    let explicitArg = null;
    const eq = argString.indexOf('=');
    if (eq !== -1) {
      optionPrefix = argString.slice(0, eq);
      explicitArg = argString.slice(eq + 1);
    }
    for (const [optionString, action] of this.optionStringActions.entries()) {
      if (optionString.startsWith(optionPrefix)) {
        result.push({ action, optionString, explicitArg });
      }
    }
    return result;
  }

  /**
   * Classify one argv entry.
   *
   * @param {string} argString
   * @returns {null | {action: object|null, optionString: string, explicitArg: string|null}}
   *   `null` means "this is a positional value".
   */
  _parseOptional(argString) {
    if (argString.length === 0) return null;
    if (!PREFIX_CHARS.includes(argString[0])) return null;

    const known = this.optionStringActions.get(argString);
    if (known !== undefined) {
      return { action: known, optionString: argString, explicitArg: null };
    }

    // A lone '-' was meant to be positional.
    if (argString.length === 1) return null;

    const eq = argString.indexOf('=');
    if (eq !== -1) {
      const optionString = argString.slice(0, eq);
      const action = this.optionStringActions.get(optionString);
      if (action !== undefined) {
        return { action, optionString, explicitArg: argString.slice(eq + 1) };
      }
    }

    const tuples = this._getOptionTuples(argString);
    if (tuples.length > 1) {
      const matches = tuples.map((t) => t.optionString).join(', ');
      this.error(`ambiguous option: ${argString} could match ${matches}`);
    } else if (tuples.length === 1) {
      return tuples[0];
    }

    // Negative numbers and anything containing a space are values, not options.
    if (NEGATIVE_NUMBER.test(argString)) return null;
    if (argString.includes(' ')) return null;

    return { action: null, optionString: argString, explicitArg: null };
  }

  /**
   * Label every argv entry as an option ('O'), a value ('A'), or the `--`
   * separator ('-'). Everything after the first `--` is forced to a value.
   *
   * @param {string[]} argv
   * @returns {{pattern: string[], classified: Array<ReturnType<ArgumentParser['_parseOptional']>>}}
   */
  _buildPattern(argv) {
    const pattern = [];
    const classified = [];
    let afterSeparator = false;

    for (const argString of argv) {
      if (afterSeparator) {
        pattern.push('A');
        classified.push(null);
        continue;
      }
      if (argString === '--') {
        pattern.push('-');
        classified.push(null);
        afterSeparator = true;
        continue;
      }
      const option = this._parseOptional(argString);
      pattern.push(option === null ? 'A' : 'O');
      classified.push(option);
    }

    return { pattern, classified };
  }

  /**
   * @param {string[]} argv arguments only, without the program name
   * @returns {{namespace: Record<string, string|undefined>, extras: string[]}}
   */
  parseKnownArgs(argv) {
    const { pattern, classified } = this._buildPattern(argv);
    /** @type {Record<string, string|undefined>} */
    const namespace = {};
    for (const action of this.actions) {
      if (action.action === 'store') namespace[action.dest] = undefined;
    }

    /** @type {string[]} */
    const extras = [];
    /** @type {Set<object>} */
    const seen = new Set();

    let i = 0;
    while (i < argv.length) {
      if (pattern[i] !== 'O') {
        // A value with nothing to consume it, or the `--` separator itself.
        extras.push(argv[i]);
        i += 1;
        continue;
      }

      const { action, optionString, explicitArg } = classified[i];
      if (action === null) {
        extras.push(argv[i]);
        i += 1;
        continue;
      }

      if (action.action === 'help') {
        throw new ExitError(0, this.formatHelp(), '');
      }

      seen.add(action);
      if (explicitArg !== null) {
        namespace[action.dest] = explicitArg;
        i += 1;
        continue;
      }
      // The value must be the very next entry, and must be a value: an option
      // or a `--` separator sitting there is an error, not a value.
      if (pattern[i + 1] === 'A') {
        namespace[action.dest] = argv[i + 1];
        i += 2;
        continue;
      }
      this.error(`argument ${optionString}: expected one argument`);
    }

    const missing = this.actions
      .filter((action) => action.required && !seen.has(action))
      .map((action) => action.optionStrings[0]);
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    return { namespace, extras };
  }

  /**
   * @param {string[]} argv arguments only, without the program name
   * @returns {Record<string, string|undefined>}
   */
  parseArgs(argv) {
    const { namespace, extras } = this.parseKnownArgs(argv);
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }
}

