    return { pattern, classified };
  }

  /**
   * @param {string[]} argv arguments only, without the program name
   * @returns {{namespace: Record<string, string|undefined>, extras: string[]}}
   */
  parseKnownArgs(argv) {
    const { pattern, classified } = this._buildPattern(argv);
    /** @type {Record<string, string|undefined>} */
    const namespace = {};
    for (const action of this.actions) {
      if (action.action === 'store') namespace[action.dest] = undefined;
    }

    /** @type {string[]} */
    const extras = [];
    /** @type {Set<object>} */
    const seen = new Set();

    let i = 0;
    while (i < argv.length) {
      if (pattern[i] !== 'O') {
        // A value with nothing to consume it, or the `--` separator itself.
        extras.push(argv[i]);
        i += 1;
        continue;
      }

      const { action, optionString, explicitArg } = classified[i];
      if (action === null) {
        extras.push(argv[i]);
        i += 1;
        continue;
      }

      if (action.action === 'help') {
        throw new ExitError(0, this.formatHelp(), '');
      }

      seen.add(action);
      if (explicitArg !== null) {
        namespace[action.dest] = explicitArg;
        i += 1;
        continue;
      }
      // The value must be the very next entry, and must be a value: an option
      // or a `--` separator sitting there is an error, not a value.
      if (pattern[i + 1] === 'A') {
        namespace[action.dest] = argv[i + 1];
        i += 2;
        continue;
      }
      this.error(`argument ${optionString}: expected one argument`);
    }

    const missing = this.actions
      .filter((action) => action.required && !seen.has(action))
      .map((action) => action.optionStrings[0]);
