/**
 * Node port of `test1.py`:
 *
 *   import argparse
 *   from deepdiff import DeepDiff
 *
 *   parser = argparse.ArgumentParser()
 *   parser.add_argument('--a', type=str, required=True)
 *   parser.add_argument('--b', type=str, required=True)
 *   args = parser.parse_args()
 *
 *   result = DeepDiff(args.a, args.b)  # 比较两个字符串的差异
 *   print(result)
 */

import { basename } from 'node:path';
import process from 'node:process';

import { ArgumentParser, ExitError } from './lib/argparse/index.mjs';
import { DeepDiff } from './lib/deepdiff/index.mjs';

function main(argv) {
  // argparse defaults prog to basename(sys.argv[0]); the Node equivalent is
  // the basename of the script being run.
  const parser = new ArgumentParser({ prog: basename(process.argv[1] ?? 'test1.mjs') });
  parser.addArgument(['--a'], { required: true });
  parser.addArgument(['--b'], { required: true });
  const args = parser.parseArgs(argv);

  const result = DeepDiff(args.a, args.b); // 比较两个字符串的差异
  console.log(String(result));
}

try {
  main(process.argv.slice(2));
} catch (error) {
  if (error instanceof ExitError) {
    if (error.stdout) process.stdout.write(error.stdout);
    if (error.stderr) process.stderr.write(error.stderr);
    process.exit(error.status);
  }
  throw error;
}

