/**
 * Randomized differential fuzzer: /output/test1.mjs vs the Python executable.
 *
 * Spawns both with an argv array (no shell), so no quoting can distort input.
 * Test scaffolding only — uses node: builtins exclusively.
 */

import { spawnSync } from 'node:child_process';
import process from 'node:process';

const PY = '/workspace/dataset/test1_executable';
const JS = '/output/test1.mjs';

let seed = Number(process.argv[3] ?? 12345);
function rnd() {
  // xorshift32: reproducible across runs
  seed ^= seed << 13; seed >>>= 0;
  seed ^= seed >>> 17;
  seed ^= seed << 5; seed >>>= 0;
  return seed / 0x100000000;
}
const randInt = (n) => Math.floor(rnd() * n);
const pick = (arr) => arr[randInt(arr.length)];

/** Line-based text: a tiny alphabet maximises repeats and near-misses. */
function randomLines(maxLines, alphabetSize) {
  const alphabet = ['a', 'b', 'c', 'x', 'y', 'foo', 'bar', '', '  indent', 'end']
    .slice(0, alphabetSize);
  const count = randInt(maxLines) + 1;
  const lines = [];
  for (let i = 0; i < count; i += 1) lines.push(pick(alphabet));
  return lines.join('\n');
}

/** Mutate text by line: delete, insert, replace, or swap. */
function mutate(text) {
  const lines = text.split('\n');
  const rounds = randInt(4) + 1;
  for (let r = 0; r < rounds; r += 1) {
    if (lines.length === 0) lines.push('new');
    const i = randInt(lines.length);
    switch (randInt(4)) {
      case 0: lines.splice(i, 1); break;
      case 1: lines.splice(i, 0, pick(['NEW', 'zzz', '', 'a'])); break;
      case 2: lines[i] = pick(['CHANGED', 'q', '', 'a']); break;
      default:
        if (i + 1 < lines.length) { const t = lines[i]; lines[i] = lines[i + 1]; lines[i + 1] = t; }
    }
  }
  return lines.join('\n');
}

/** Characters chosen to exercise repr: quotes, escapes, line boundaries, categories. */
const SPICY = [
  "'", '"', '\\', '\t', '\n', '\r', '\v', '\f', '\x1c', '\x1d', '\x1e',
  '\x85', ' ', ' ', '\x00'.replace('\x00', '\x01'), '\x7f', '\x1b',
  '\xa0', '\xad', '​', '﻿', ' ', 'a', 'Z', '0',
  'é', '→', '中', '🎉', '\u{e0001}', '\u{10ffff}', '́', 'ß',
];

function randomSpicy(maxLen) {
  const count = randInt(maxLen) + 1;
  let s = '';
  for (let i = 0; i < count; i += 1) s += pick(SPICY);
  return s;
}

function run(cmd, args, argv) {
  const r = spawnSync(cmd, [...args, ...argv], { encoding: 'utf8', maxBuffer: 1 << 28 });
  return { out: r.stdout ?? '', err: r.stderr ?? '', code: r.status };
}

const mode = process.argv[2] ?? 'lines';
const iterations = Number(process.argv[4] ?? 200);
let pass = 0;
const failures = [];

for (let iter = 0; iter < iterations; iter += 1) {
  let a;
  let b;
  if (mode === 'lines') {
    a = randomLines(12, 6);
    b = rnd() < 0.85 ? mutate(a) : randomLines(12, 6);
  } else if (mode === 'big') {
    // Cross the autojunk threshold (len(b) >= 200).
    a = randomLines(400, 4);
    b = mutate(a);
  } else {
    a = randomSpicy(10);
    b = rnd() < 0.5 ? randomSpicy(10) : a;
  }

  const argv = ['--a', a, '--b', b];
  const py = run(PY, [], argv);
  const js = run('node', [JS], argv);

  const norm = (s) => s.replaceAll('test1_executable', 'PROG').replaceAll('test1.mjs', 'PROG');
  if (py.out === js.out && py.code === js.code && norm(py.err) === norm(js.err)) {
    pass += 1;
  } else {
    failures.push({ a, b, py, js });
  }
}

console.log(`mode=${mode} pass=${pass}/${iterations} fail=${failures.length}`);
for (const f of failures.slice(0, 3)) {
  console.log('--- FAIL ---');
  console.log('a =', JSON.stringify(f.a));
  console.log('b =', JSON.stringify(f.b));
  console.log('py out:', JSON.stringify(f.py.out));
  console.log('js out:', JSON.stringify(f.js.out));
  if (f.py.code !== f.js.code) console.log('codes:', f.py.code, f.js.code);
  if (f.py.err !== f.js.err) { console.log('py err:', f.py.err); console.log('js err:', f.js.err); }
}
process.exit(failures.length === 0 ? 0 : 1);

